function StatusPill({ status }: { status: string }) {
  const tone = status === 'Active' || status === 'Complete' || status === 'Indexed' ? 'green' : status === 'In Progress' || status === 'Processing' ? 'blue' : status === 'Needs Review' || status === 'Needs review' ? 'amber' : 'gray';
  return <span data-testid={`status-${status.toLowerCase().replace(/\s/g, '-')}`} className={`status-pill status-${tone}`}><span className="status-dot" />{status}</span>;
}

function Button({ children, onClick, variant = 'primary', className = '', type = 'button', disabled = false, testId }: { children: ReactNode; onClick?: () => void; variant?: 'primary' | 'secondary' | 'ghost' | 'danger'; className?: string; type?: 'button' | 'submit'; disabled?: boolean; testId?: string }) {
  return <button data-testid={testId} type={type} disabled={disabled} onClick={onClick} className={cx('inline-flex items-center justify-center gap-2 rounded-md px-3.5 py-2 text-xs font-bold transition focus-ring disabled:cursor-not-allowed disabled:opacity-50', variant === 'primary' && 'bg-[#24558d] text-white hover:bg-[#1d4778]', variant === 'secondary' && 'border border-[#d7dde5] bg-white text-[#34445a] hover:bg-[#f4f6f8]', variant === 'ghost' && 'text-[#657287] hover:bg-[#eef2f6] hover:text-[#1f4e82]', variant === 'danger' && 'bg-[#b94843] text-white hover:bg-[#963a36]', className)}>{children}</button>;
}

function Field({ label, value, onChange, placeholder, type = 'text', icon, required = false }: { label: string; value: string; onChange: (value: string) => void; placeholder?: string; type?: string; icon?: ReactNode; required?: boolean }) {
  return <label className="block space-y-1.5"><span className="label-caps text-[10px]">{label}{required && <span className="ml-1 text-[#b94843]">*</span>}</span><span className="relative block">{icon && <span className="pointer-events-none absolute left-3 top-2.5 text-[#8995a7]">{icon}</span>}<input data-testid={`input-${label.toLowerCase().replace(/\s/g, '-')}`} type={type} value={value} onChange={e => onChange(e.target.value)} placeholder={placeholder} className={cx('h-10 w-full rounded-md border border-[#d9dfe7] bg-white px-3 text-sm text-[#1f2e43] placeholder:text-[#a4adba] outline-none transition focus:border-[#5688bd] focus:ring-2 focus:ring-[#dceafb]', icon ? 'pl-9' : false)} /></span></label>;
}

function Modal({ title, children, onClose, width = 'max-w-lg' }: { title: string; children: ReactNode; onClose: () => void; width?: string }) {
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#0f1b2d]/45 p-4 backdrop-blur-[2px]" onMouseDown={e => { if (e.target === e.currentTarget) onClose(); }}><div className={cx('slide-in max-h-[90vh] w-full overflow-y-auto rounded-lg bg-white shadow-2xl', width)}><div className="flex items-center justify-between border-b border-[#e7eaf0] px-6 py-4"><h2 className="text-base font-bold text-[#172a43]">{title}</h2><button data-testid="button-close-modal" onClick={onClose} className="rounded p-1 text-[#8a95a5] hover:bg-[#f1f4f7] hover:text-[#1f2e43]"><X size={18} /></button></div>{children}</div></div>;
}

