        <div className="rounded-md border border-[#263a54] bg-[#14263d] p-3"><div className="flex items-center gap-2 text-[11px] font-semibold text-white"><span className={cx('h-1.5 w-1.5 rounded-full', archiveActive ? 'bg-[#52cf99]' : 'bg-[#d4a843]')} />{archiveActive ? 'Archive active' : 'Archive paused'}</div><div className="mt-1 pl-3.5 text-[9px] text-[#8595aa]">Local storage connected</div></div>
