function Login({ onLogin }: { onLogin: (identity: SessionIdentity) => Promise<void> }) {
  const [role, setRole] = useState<UserRole>('Regular User');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [remember, setRemember] = useState(true);
  const [feedback, setFeedback] = useState('');
  const submit = async (e: React.FormEvent) => { e.preventDefault(); if (!email || !password) { setFeedback('Enter your credentials to continue.'); return; } const response = await fetch('/api/session/login', { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email, password, role }) }); if (!response.ok) { setFeedback('Unable to start this archive session.'); return; } const identity = await response.json() as SessionIdentity; localStorage.setItem('adzu-auth', 'true'); localStorage.setItem('adzu-role', identity.role); if (remember) localStorage.setItem('adzu-remember', 'true'); await onLogin(identity); };
  return <div className="flex min-h-[100dvh] bg-[#f4f6f9]"><section className="login-grid relative hidden w-[62%] overflow-hidden bg-[#1d4277] lg:flex lg:flex-col lg:items-center lg:justify-center"><div className="absolute inset-0 bg-gradient-to-br from-[#183c70] via-[#24558d] to-[#2f66a5] opacity-90" /><div className="relative z-10 flex max-w-[600px] flex-col items-center text-center"><img src="/figma-reference/adzu-seal.png" alt="ADZU seal" className="mb-8 h-[172px] w-[172px] object-contain drop-shadow-xl" /><h1 className="max-w-[560px] text-[31px] font-bold leading-[1.13] tracking-[-.04em] text-white">Ateneo de Zamboanga University<br />Registrar’s Office</h1><p className="mt-5 max-w-[470px] text-sm leading-6 text-[#c2d2e7]">A quiet, secure archive for the records that shape every student’s journey.</p></div><div className="absolute bottom-7 left-9 z-10 text-[9px] leading-4 text-[#b7cbe3]"><strong className="text-white">Ateneo de Zamboanga University — Secure Document Management</strong><br />Official Records &amp; Archives Management Office</div></section><section className="flex flex-1 items-center justify-center px-5 py-10"><div className="w-full max-w-[380px]"><div className="mb-8 lg:hidden"><Logo /></div><div className="rounded-xl border border-[#e2e6eb] bg-white p-7 shadow-[0_10px_35px_rgba(15,27,45,.08)] sm:p-9"><div className="mb-7 text-center"><div className="text-[18px] font-bold tracking-[-.03em] text-[#182a43]">Portal Authentication</div><p className="mt-1.5 text-xs text-[#8290a1]">Please enter your credentials to access archives</p></div><div className="mb-6 grid grid-cols-2 rounded-md bg-[#f0f3f7] p-1"><button data-testid="tab-regular-user" onClick={() => setRole('Regular User')} className={cx('rounded py-2 text-[11px] font-bold', role === 'Regular User' ? 'bg-[#1f4d82] text-white shadow-sm' : 'text-[#8793a3]')}>Regular User</button><button data-testid="tab-admin" onClick={() => setRole('Admin')} className={cx('rounded py-2 text-[11px] font-bold', role === 'Admin' ? 'bg-[#1f4d82] text-white shadow-sm' : 'text-[#8793a3]')}>Admin</button></div><form className="space-y-4" onSubmit={submit}><Field label="Username or Institutional Email" value={email} onChange={setEmail} placeholder="username@adzu.edu.ph" icon={<UserRound size={14} />} required /><div><div className="relative"><Field label="Password" value={password} onChange={setPassword} placeholder="Enter your password" type={showPassword ? 'text' : 'password'} icon={<LockKeyhole size={14} />} required /><button data-testid="button-toggle-password" type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-3 top-[27px] text-[#8b97a6]">{showPassword ? <EyeOff size={15} /> : <Eye size={15} />}</button></div></div><div className="flex items-center justify-between text-[10px]"><label className="flex items-center gap-2 text-[#627187]"><input data-testid="checkbox-remember-me" type="checkbox" checked={remember} onChange={e => setRemember(e.target.checked)} className="h-3.5 w-3.5 accent-[#1f4d82]" />Remember me</label><button data-testid="button-forgot-password" type="button" onClick={() => setFeedback('A password reset link would be sent to your institutional email.')} className="font-bold text-[#24558d] hover:underline">Forgot Password?</button></div>{feedback && <div data-testid="text-login-feedback" className="rounded-md bg-[#fff6df] px-3 py-2 text-[11px] text-[#8c691a]">{feedback}</div>}<Button type="submit" testId="button-login" className="mt-2 w-full py-2.5">Log in</Button></form></div><p className="mt-3 text-center text-[10px] text-[#9aa4b1]">© 2024 Ateneo de Zamboanga University</p></div></section></div>;
}

function PageHeader({ eyebrow, title, description, actions }: { eyebrow: string; title: string; description?: string; actions?: ReactNode }) {
  return <div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><div className="label-caps mb-2">{eyebrow}</div><h1 className="text-[25px] font-bold tracking-[-.04em] text-[#182a43]">{title}</h1>{description && <p className="mt-1.5 text-sm text-[#718096]">{description}</p>}</div>{actions && <div className="flex items-center gap-2">{actions}</div>}</div>;
}
function EmptyState({ icon: Icon, title, body }: { icon: typeof Archive; title: string; body: string }) {
  return <div className="flex flex-col items-center justify-center px-6 py-14 text-center"><div className="mb-3 rounded-full bg-[#edf2f7] p-3 text-[#6c8199]"><Icon size={21} /></div><div className="text-sm font-bold text-[#34445a]">{title}</div><p className="mt-1 max-w-xs text-xs leading-5 text-[#8a96a5]">{body}</p></div>;
}
function RegularDashboard({ folders, uploads, activity, archiveActive }: { folders: StudentFolder[]; uploads: UploadRecord[]; activity: ActivityItem[]; archiveActive: boolean }) {
  const complete = folders.filter(folder => folder.status === 'Complete').length;
  return <div className="mx-auto max-w-[1420px] p-5 sm:p-7"><PageHeader eyebrow="Registrar e-Archiving System" title="Archive Dashboard" description="Your read-only view of student records." /><div className="grid gap-4 md:grid-cols-3"><StatCard label="Student folders" value={folders.length} helper={`${complete} folders complete`} icon={<Folder size={17} />} tone="navy" /><StatCard label="Indexed documents" value={uploads.length + folders.reduce((sum, folder) => sum + folder.documentCount, 0)} helper="Available to view and print" icon={<FileText size={17} />} tone="gold" /><StatCard label="Archive status" value={archiveActive ? 'Active' : 'Paused'} helper="Managed by an Admin" icon={archiveActive ? <CircleCheck size={18} /> : <CircleAlert size={18} />} tone={archiveActive ? 'green' : 'amber'} /></div><section className="surface-card mt-5 rounded-lg"><div className="border-b border-[#e8ebef] px-5 py-4"><div><h2 className="text-sm font-bold text-[#1c2f47]">Your recent activity</h2><p className="mt-0.5 text-[11px] text-[#8a95a5]">Only actions performed by your account are shown.</p></div></div>{activity.length ? <div className="divide-y divide-[#edf0f3]">{activity.slice(0, 5).map(item => <ActivityRow key={item.id} item={item} />)}</div> : <EmptyState icon={Activity} title="No recent activity" body="Your searches, folder views, and document views will appear here." />}</section></div>;
}

function SearchResults({ folders, addActivity, setLocation }: { folders: StudentFolder[]; addActivity: (action: string, subject: string, metadata?: { folder?: string; document?: string }) => void; setLocation: (path: string) => void }) {
  const [query, setQuery] = useState('');
  const visible = folders.filter(folder => `${folder.studentName} ${folder.studentId}`.toLowerCase().includes(query.toLowerCase()));
  return <div className="mx-auto max-w-[1000px] p-5 sm:p-7"><PageHeader eyebrow="Records lookup" title="Search student records" description="Search by Student Name or Student ID. Results show matching student records only." /><div className="surface-card rounded-lg"><div className="border-b border-[#e8ebef] p-5"><div className="relative max-w-2xl"><Search size={15} className="absolute left-3 top-2.5 text-[#8a97a7]" /><input autoFocus data-testid="input-student-search" value={query} onChange={e => setQuery(e.target.value)} onKeyDown={e => { if (e.key === 'Enter' && query.trim()) addActivity('Searched records', query.trim()); }} placeholder="Search by student name or Student ID" className="h-10 w-full rounded-md border border-[#d9dfe7] pl-9 pr-3 text-sm outline-none focus:border-[#5688bd]" /></div></div><div className="divide-y divide-[#edf0f3]">{visible.map(folder => <div key={folder.id} data-testid={`search-result-${folder.id}`} className="flex items-center gap-4 px-5 py-4"><div className="flex h-9 w-9 items-center justify-center rounded-md bg-[#eaf0f7] text-[10px] font-bold text-[#315c87]">{folder.studentName.split(' ').map(x => x[0]).slice(0, 2).join('')}</div><div className="flex-1"><div className="text-xs font-bold text-[#263950]">{folder.studentName}</div><div className="mono mt-1 text-[10px] text-[#8995a4]">{folder.studentId}</div></div><span className="text-xs text-[#718096]">{folder.documentCount} files</span></div>)}{!visible.length && <EmptyState icon={Search} title="No matching students" body="Try the student's full name or Student ID." />}</div></div></div>;
}

function LegacyDashboard({ folders, documents, uploads, activity, archiveActive, setArchiveActive, setLocation }: { folders: StudentFolder[]; documents: DocumentType[]; uploads: UploadRecord[]; activity: ActivityItem[]; archiveActive: boolean; setArchiveActive: (value: boolean) => void; setLocation: (path: string) => void }) {
  const complete = folders.filter(f => f.status === 'Complete').length;
  return <div className="mx-auto max-w-[1420px] p-5 sm:p-7"><PageHeader eyebrow="Registrar e-Archiving System" title="Archive Dashboard" description="Current state of the local student document archive." actions={<><Button variant="secondary" onClick={() => setLocation('/upload')}><Upload size={14} />Upload document</Button><Button onClick={() => setLocation('/folders')}><FolderOpen size={14} />Browse folders</Button></>} /><div className="grid gap-4 md:grid-cols-3"><StatCard label="Total folders" value={folders.length} helper={`${complete} folders complete`} icon={<Folder size={17} />} tone="navy" /><StatCard label="Total documents" value={uploads.length + folders.reduce((sum, f) => sum + f.documentCount, 0)} helper={`${uploads.length} recently indexed`} icon={<FileText size={17} />} tone="gold" /><StatCard label="Archive status" value={archiveActive ? 'Active' : 'Paused'} helper={archiveActive ? 'Local repository connected' : 'Uploads are currently paused'} icon={archiveActive ? <CircleCheck size={18} /> : <CircleAlert size={18} />} tone={archiveActive ? 'green' : 'amber'} /></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.1fr_.9fr]"><section className="surface-card rounded-lg"><div className="flex items-center justify-between border-b border-[#e8ebef] px-5 py-4"><div><h2 className="text-sm font-bold text-[#1c2f47]">Recent activity</h2><p className="mt-0.5 text-[11px] text-[#8a95a5]">A record of the latest archive actions.</p></div><button data-testid="link-view-activity" onClick={() => setLocation('/activity')} className="text-[11px] font-bold text-[#24558d] hover:underline">View all</button></div>{activity.length ? <div className="divide-y divide-[#edf0f3]">{activity.slice(0, 5).map(item => <ActivityRow key={item.id} item={item} />)}</div> : <EmptyState icon={Activity} title="No recent activity" body="Actions taken in the archive will appear here." />}</section><section className="surface-card rounded-lg"><div className="flex items-center justify-between border-b border-[#e8ebef] px-5 py-4"><div><h2 className="text-sm font-bold text-[#1c2f47]">Archive location</h2><p className="mt-0.5 text-[11px] text-[#8a95a5]">Where local records are stored.</p></div><StatusPill status={archiveActive ? 'Active' : 'Paused'} /></div><div className="p-5"><div className="flex items-center gap-3 rounded-md bg-[#f3f5f7] px-4 py-3 text-xs text-[#47576b]"><HardDrive size={16} className="text-[#627b98]" /><span className="mono text-[10px]">/Users/registrar/Documents/adzu-archive</span></div><div className="mt-5 flex items-center justify-between border-t border-[#edf0f3] pt-4"><div><div className="text-xs font-bold text-[#35465a]">Archive controls</div><div className="mt-1 text-[11px] text-[#8793a3]">Manage the availability of local storage.</div></div><button data-testid="button-toggle-archive-dashboard" onClick={() => setArchiveActive(!archiveActive)} className={cx('relative h-6 w-11 rounded-full transition', archiveActive ? 'bg-[#2b9b72]' : 'bg-[#a9b4c0')}><span className={cx('absolute top-1 h-4 w-4 rounded-full bg-white shadow-sm transition-transform', archiveActive ? 'translate-x-6' : 'translate-x-1')} /></button></div></div></section></div><section className="mt-5 grid gap-4 sm:grid-cols-3"><MiniSummary icon={<FileArchive size={17} />} label="Document types" value={documents.length} action="Manage types" onClick={() => setLocation('/documents')} /><MiniSummary icon={<Upload size={17} />} label="Pending uploads" value={uploads.filter(x => x.status !== 'Indexed').length} action="Review uploads" onClick={() => setLocation('/upload')} /><MiniSummary icon={<ShieldCheck size={17} />} label="Indexed records" value={uploads.filter(x => x.status === 'Indexed').length} action="Open activity" onClick={() => setLocation('/activity')} /></section></div>;
}
function StatCard({ label, value, helper, icon, tone }: { label: string; value: string | number; helper: string; icon: ReactNode; tone: string }) {
  return <div className="surface-card rounded-lg p-5"><div className="flex items-start justify-between"><div><div className="label-caps">{label}</div><div className={cx('mt-2 text-[27px] font-bold tracking-[-.04em]', tone === 'green' ? 'text-[#278763]' : tone === 'amber' ? 'text-[#a9791d]' : 'text-[#1c2f47]')}>{value}</div></div><div className={cx('rounded-full p-2.5', tone === 'gold' ? 'bg-[#fff6df] text-[#ab7e20]' : tone === 'green' ? 'bg-[#e5f5ee] text-[#2b9b72]' : tone === 'amber' ? 'bg-[#fff6df] text-[#b17f22]' : 'bg-[#edf2f7] text-[#536d89]')}>{icon}</div></div><div className="mt-1 text-[11px] text-[#8490a0]">{helper}</div></div>;
}
function MiniSummary({ icon, label, value, action, onClick }: { icon: ReactNode; label: string; value: number; action: string; onClick: () => void }) {
  return <div className="surface-card flex items-center gap-3 rounded-lg p-4"><div className="rounded-md bg-[#edf2f7] p-2 text-[#536d89]">{icon}</div><div className="min-w-0 flex-1"><div className="text-[11px] text-[#8692a1]">{label}</div><div className="text-lg font-bold text-[#263950]">{value}</div></div><button data-testid={`button-${action.toLowerCase().replace(/\s/g, '-')}`} onClick={onClick} className="text-[10px] font-bold text-[#24558d] hover:underline">{action}</button></div>;
}
function ActivityRow({ item }: { item: ActivityItem }) {
  return <div data-testid={`activity-row-${item.id}`} className="flex items-start gap-3 px-5 py-3.5"><div className="mt-0.5 rounded-full bg-[#edf2f7] p-2 text-[#567493]"><Activity size={13} /></div><div className="min-w-0 flex-1"><div className="text-xs text-[#33465e]"><strong className="font-bold">{item.action}</strong> <span className="text-[#718096]">{item.subject}</span></div><div className="mt-1 text-[10px] text-[#98a1ad]">{item.actor} · {item.role ?? 'Admin'} · {formatRelative(item.timestamp)}</div></div><StatusPill status={item.status ?? 'Success'} /></div>;
}

function LegacyFolders({ folders, setFolders, addActivity, setLocation, role, searchOnly = false }: { folders: StudentFolder[]; setFolders: (v: StudentFolder[]) => void; addActivity: (action: string, subject: string, metadata?: { folder?: string; document?: string }) => void; setLocation: (path: string) => void; role: UserRole; searchOnly?: boolean }) {
  const [query, setQuery] = useState(''); const [status, setStatus] = useState('All statuses'); const [sort, setSort] = useState('Recently updated'); const [selected, setSelected] = useState<StudentFolder | null>(null);
  const visible = useMemo(() => folders.filter(f => (status === 'All statuses' || f.status === status) && `${f.studentName} ${f.studentId} ${f.program}`.toLowerCase().includes(query.toLowerCase())).sort((a, b) => sort === 'Name A–Z' ? a.studentName.localeCompare(b.studentName) : new Date(b.lastUpdated).getTime() - new Date(a.lastUpdated).getTime()), [folders, query, status, sort]);
  return <div className="mx-auto max-w-[1420px] p-5 sm:p-7"><PageHeader eyebrow="Archive management" title="Student Folders" description="Browse and review the student records held in the archive." actions={<Button onClick={() => setLocation('/upload')}><Plus size={14} />Add document</Button>} /><div className="surface-card rounded-lg"><div className="flex flex-col gap-3 border-b border-[#e8ebef] p-4 lg:flex-row lg:items-center"><div className="relative flex-1"><Search size={15} className="absolute left-3 top-2.5 text-[#8a97a7]" /><input data-testid="input-search-folders" value={query} onChange={e => setQuery(e.target.value)} placeholder="Search by student name, ID, or program" className="h-9 w-full rounded-md border border-[#d9dfe7] pl-9 pr-3 text-xs outline-none focus:border-[#5688bd]" /></div><div className="flex gap-2"><select data-testid="select-folder-status" value={status} onChange={e => setStatus(e.target.value)} className="h-9 rounded-md border border-[#d9dfe7] bg-white px-3 text-xs text-[#47576b] outline-none"><option>All statuses</option><option>Complete</option><option>In Progress</option><option>Needs Review</option></select><select data-testid="select-folder-sort" value={sort} onChange={e => setSort(e.target.value)} className="h-9 rounded-md border border-[#d9dfe7] bg-white px-3 text-xs text-[#47576b] outline-none"><option>Recently updated</option><option>Name A–Z</option></select></div></div><div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left"><thead><tr className="border-b border-[#e8ebef] bg-[#fafbfc] text-[10px] uppercase tracking-[.1em] text-[#8a96a5]"><th className="px-5 py-3 font-bold">Student</th><th className="px-4 py-3 font-bold">Program</th><th className="px-4 py-3 font-bold">Documents</th><th className="px-4 py-3 font-bold">Status</th><th className="px-4 py-3 font-bold">Last updated</th><th className="px-5 py-3" /></tr></thead><tbody className="divide-y divide-[#edf0f3]">{visible.map(folder => <tr data-testid={`row-folder-${folder.id}`} key={folder.id} className="group hover:bg-[#fbfcfd]"><td className="px-5 py-3.5"><div className="flex items-center gap-3"><div className="flex h-8 w-8 items-center justify-center rounded-md bg-[#eaf0f7] text-[10px] font-bold text-[#315c87]">{folder.studentName.split(' ').map(x => x[0]).slice(0, 2).join('')}</div><div><div className="text-xs font-bold text-[#263950]">{folder.studentName}</div><div className="mono mt-0.5 text-[10px] text-[#8995a4]">{folder.studentId}</div></div></div></td><td className="px-4 py-3.5 text-xs text-[#617084]">{folder.program}</td><td className="px-4 py-3.5 text-xs font-semibold text-[#3f5065]">{folder.documentCount} <span className="font-normal text-[#9aa3ae]">files</span></td><td className="px-4 py-3.5"><StatusPill status={folder.status} /></td><td className="px-4 py-3.5 text-xs text-[#718096]">{formatDate(folder.lastUpdated)}</td><td className="px-5 py-3.5 text-right"><Button variant="ghost" onClick={() => setSelected(folder)} className="px-2" testId={`button-view-folder-${folder.id}`}><Eye size={14} /></Button></td></tr>)}</tbody></table>{!visible.length && <EmptyState icon={FolderOpen} title="No folders found" body="Try adjusting your search or status filter." />}</div><div className="flex items-center justify-between border-t border-[#e8ebef] px-5 py-3 text-[10px] text-[#8a95a5]"><span>Showing {visible.length} of {folders.length} folders</span><div className="flex gap-1"><button data-testid="button-folders-prev" className="rounded border border-[#e0e5eb] p-1.5 text-[#9aa4b1]"><ChevronLeft size={13} /></button><button data-testid="button-folders-next" className="rounded border border-[#e0e5eb] p-1.5 text-[#9aa4b1]"><ChevronRight size={13} /></button></div></div></div>{selected && <FolderDrawer folder={selected} onClose={() => setSelected(null)} onUpdate={folder => { setFolders(folders.map(f => f.id === folder.id ? folder : f)); addActivity('Updated folder', `${folder.studentName} · ${folder.studentId}`); setSelected(folder); }} />}</div>;
}
function LegacyReadOnlyFolders({ folders, addActivity, title = 'Search student records' }: { folders: StudentFolder[]; addActivity: (action: string, subject: string, metadata?: { folder?: string; document?: string }) => void; title?: string }) {
  const [query, setQuery] = useState(''); const [selected, setSelected] = useState<StudentFolder | null>(null);
  const visible = folders.filter(folder => `${folder.studentName} ${folder.studentId}`.toLowerCase().includes(query.toLowerCase()));
  return <div className="mx-auto max-w-[1420px] p-5 sm:p-7"><PageHeader eyebrow="Records lookup" title={title} description="Regular Users can search, open folders, view documents, and print documents." /><div className="surface-card rounded-lg"><div className="border-b border-[#e8ebef] p-4"><div className="relative max-w-xl"><Search size={15} className="absolute left-3 top-2.5 text-[#8a97a7]" /><input data-testid="input-search-records" value={query} onChange={e => setQuery(e.target.value)} placeholder="Search by Student ID or student name" className="h-9 w-full rounded-md border border-[#d9dfe7] pl-9 pr-3 text-xs outline-none focus:border-[#5688bd]" /></div></div><div className="divide-y divide-[#edf0f3]">{visible.map(folder => <button key={folder.id} data-testid={`readonly-folder-${folder.id}`} onClick={() => { setSelected(folder); addActivity('Viewed folder', folder.studentName, { folder: folder.studentName }); }} className="flex w-full items-center gap-4 px-5 py-4 text-left hover:bg-[#fbfcfd]"><div className="flex h-9 w-9 items-center justify-center rounded-md bg-[#eaf0f7] text-[10px] font-bold text-[#315c87]">{folder.studentName.split(' ').map(x => x[0]).slice(0, 2).join('')}</div><div className="flex-1"><div className="text-xs font-bold text-[#263950]">{folder.studentName}</div><div className="mono mt-1 text-[10px] text-[#8995a4]">{folder.studentId} · {folder.program}</div></div><span className="text-xs text-[#718096]">{folder.documentCount} files</span><ChevronRight size={15} className="text-[#9aa4b1]" /></button>)}{!visible.length && <EmptyState icon={FolderOpen} title="No student records found" body="Try a different Student ID or name." />}</div></div>{selected && <ReadOnlyFolderViewer folder={selected} onClose={() => setSelected(null)} onActivity={addActivity} />}</div>;
}

function LegacyReadOnlyFolderViewer({ folder, onClose, onActivity }: { folder: StudentFolder; onClose: () => void; onActivity: (action: string, subject: string, metadata?: { folder?: string; document?: string }) => void }) {
  const documents = ['Transcript of Records', 'Student Permanent Record', 'Government ID', 'Certificate of Graduation'].slice(0, Math.min(4, folder.documentCount)); const [document, setDocument] = useState<string | null>(null);
  return <div className="fixed inset-0 z-40 bg-[#0f1b2d]/35" onMouseDown={e => { if (e.target === e.currentTarget) onClose(); }}><div className="slide-in absolute right-0 top-0 h-full w-full max-w-[470px] overflow-y-auto bg-white shadow-2xl"><div className="flex items-center justify-between border-b border-[#e7eaf0] px-6 py-5"><div><div className="label-caps">Read-only folder</div><h2 className="mt-1 text-lg font-bold text-[#182a43]">{folder.studentName}</h2></div><button onClick={onClose} className="rounded p-1.5 text-[#8a95a5] hover:bg-[#f1f4f7]"><X size={18} /></button></div><div className="space-y-5 p-6"><div className="rounded-lg bg-[#f4f7fa] p-4"><div className="mono text-xs font-bold text-[#34445a]">{folder.studentId}</div><div className="mt-1 text-xs text-[#758397]">{folder.program}</div></div><div><div className="label-caps mb-2">Documents</div><div className="space-y-2">{documents.map(name => <button key={name} onClick={() => { setDocument(name); onActivity('Viewed document', name, { folder: folder.studentName, document: name }); }} className="flex w-full items-center gap-2 rounded-md border border-[#edf0f3] px-3 py-3 text-left hover:border-[#b9cbe0]"><FileCheck2 size={14} className="text-[#2b9b72]" /><span className="flex-1 text-xs text-[#4a5b70]">{name}</span><Eye size={14} className="text-[#6d839d]" /></button>)}</div></div>{document && <div className="rounded-lg border border-[#dce5ee] bg-[#f8fafc] p-4"><div className="label-caps">Document viewer</div><div className="mt-2 text-xs font-bold text-[#263950]">{document}</div><div className="mt-2 h-28 rounded border border-dashed border-[#c9d5e1] bg-white p-4 text-center text-[11px] text-[#8492a3]">Document preview available for viewing and printing.</div><Button className="mt-3 w-full" onClick={() => { onActivity('Printed document', document, { folder: folder.studentName, document }); window.print(); }}><Printer size={14} />Print document</Button></div>}</div></div></div>;
}

function LegacyFolderDrawer({ folder, onClose, onUpdate }: { folder: StudentFolder; onClose: () => void; onUpdate: (folder: StudentFolder) => void }) {
  const [status, setStatus] = useState(folder.status);
  return <div className="fixed inset-0 z-40 bg-[#0f1b2d]/35" onMouseDown={e => { if (e.target === e.currentTarget) onClose(); }}><div className="slide-in absolute right-0 top-0 h-full w-full max-w-[430px] overflow-y-auto bg-white shadow-2xl"><div className="flex items-center justify-between border-b border-[#e7eaf0] px-6 py-5"><div><div className="label-caps">Folder details</div><h2 className="mt-1 text-lg font-bold text-[#182a43]">{folder.studentName}</h2></div><button data-testid="button-close-folder-drawer" onClick={onClose} className="rounded p-1.5 text-[#8a95a5] hover:bg-[#f1f4f7]"><X size={18} /></button></div><div className="space-y-6 p-6"><div className="flex items-center gap-3 rounded-lg bg-[#f4f7fa] p-4"><div className="flex h-11 w-11 items-center justify-center rounded-md bg-[#dfeaf5] font-bold text-[#315c87]">{folder.studentName.split(' ').map(x => x[0]).slice(0, 2).join('')}</div><div><div className="mono text-xs font-bold text-[#34445a]">{folder.studentId}</div><div className="mt-1 text-xs text-[#758397]">{folder.program}</div></div></div><div className="grid grid-cols-2 gap-3"><div className="rounded-md border border-[#e7ebef] p-3"><div className="label-caps">Documents</div><div className="mt-2 text-xl font-bold text-[#263950]">{folder.documentCount}</div></div><div className="rounded-md border border-[#e7ebef] p-3"><div className="label-caps">Last updated</div><div className="mt-2 text-xs font-bold text-[#263950]">{formatDate(folder.lastUpdated)}</div></div></div><div><div className="label-caps mb-2">Folder status</div><select data-testid="select-drawer-status" value={status} onChange={e => setStatus(e.target.value as FolderStatus)} className="h-10 w-full rounded-md border border-[#d9dfe7] bg-white px-3 text-xs text-[#47576b]"><option>Complete</option><option>In Progress</option><option>Needs Review</option></select></div><div><div className="mb-2 flex items-center justify-between"><div className="label-caps">Document inventory</div><span className="text-[10px] text-[#8a95a5]">Latest scan</span></div><div className="space-y-2">{['Transcript of Records', 'Student Permanent Record', 'Government ID', 'Certificate of Graduation'].slice(0, Math.min(4, folder.documentCount)).map((name, i) => <div className="flex items-center gap-2 rounded-md border border-[#edf0f3] px-3 py-2.5" key={name}><FileCheck2 size={14} className="text-[#2b9b72]" /><span className="flex-1 text-xs text-[#4a5b70]">{name}</span><span className="text-[10px] text-[#9aa4b1]">{i === 0 ? 'Today' : 'Indexed'}</span></div>)}</div></div><Button className="w-full" onClick={() => onUpdate({ ...folder, status, lastUpdated: new Date().toISOString() })} testId="button-save-folder">Save folder status</Button></div></div></div>;
}

function Dashboard({ folders, documents, uploads, activity, archiveActive, archiveDestination, onArchiveToggle, setLocation }: { folders: StudentFolder[]; documents: DocumentType[]; uploads: UploadRecord[]; activity: ActivityItem[]; archiveActive: boolean; archiveDestination: string; onArchiveToggle: (value: boolean) => void; setLocation: (path: string) => void }) {
  const complete = folders.filter(f => f.status === 'Complete').length;
  return <div className="mx-auto max-w-[1420px] p-5 sm:p-7"><PageHeader eyebrow="Registrar e-Archiving System" title="Archive Dashboard" description="Current state of the local student document archive." actions={<><Button variant="secondary" onClick={() => setLocation('/upload')}><Upload size={14} />Upload document</Button><Button onClick={() => setLocation('/folders')}><FolderOpen size={14} />Browse folders</Button></>} /><div className="grid gap-4 md:grid-cols-3"><StatCard label="Total folders" value={folders.length} helper={`${complete} folders complete`} icon={<Folder size={17} />} tone="navy" /><StatCard label="Total documents" value={uploads.length + folders.reduce((sum, f) => sum + f.documentCount, 0)} helper={`${uploads.length} recently indexed`} icon={<FileText size={17} />} tone="gold" /><StatCard label="Archive status" value={archiveActive ? 'Active' : 'Paused'} helper={archiveActive ? 'Local repository connected' : 'Uploads are currently paused'} icon={archiveActive ? <CircleCheck size={18} /> : <CircleAlert size={18} />} tone={archiveActive ? 'green' : 'amber'} /></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.1fr_.9fr]"><section className="surface-card rounded-lg"><div className="flex items-center justify-between border-b border-[#e8ebef] px-5 py-4"><div><h2 className="text-sm font-bold text-[#1c2f47]">Recent activity</h2><p className="mt-0.5 text-[11px] text-[#8a95a5]">A record of the latest archive actions.</p></div><button data-testid="link-view-activity" onClick={() => setLocation('/activity')} className="text-[11px] font-bold text-[#24558d] hover:underline">View all</button></div>{activity.length ? <div className="divide-y divide-[#edf0f3]">{activity.slice(0, 5).map(item => <ActivityRow key={item.id} item={item} />)}</div> : <EmptyState icon={Activity} title="No recent activity" body="Actions taken in the archive will appear here." />}</section><section className="surface-card rounded-lg"><div className="border-b border-[#e8ebef] px-5 py-4"><div><h2 className="text-sm font-bold text-[#1c2f47]">Archive location</h2><p className="mt-0.5 text-[11px] text-[#8a95a5]">Where local records are stored.</p></div></div><div className="p-5"><div className="flex items-center gap-3 rounded-md bg-[#f3f5f7] px-4 py-3 text-xs text-[#47576b]"><HardDrive size={16} className="text-[#627b98]" /><span className="mono break-all text-[10px]">{archiveDestination}</span></div><div className="mt-5 flex items-center justify-between border-t border-[#edf0f3] pt-4"><div><div className="text-xs font-bold text-[#35465a]">Archive controls</div><div className="mt-1 text-[11px] text-[#8793a3]">Manage the availability of local storage.</div></div><button data-testid="button-toggle-archive-dashboard" onClick={() => onArchiveToggle(!archiveActive)} className={cx('relative h-6 w-11 rounded-full transition', archiveActive ? 'bg-[#2b9b72]' : 'bg-[#a9b4c0]')}><span className={cx('absolute top-1 h-4 w-4 rounded-full bg-white shadow-sm transition-transform', archiveActive ? 'translate-x-6' : 'translate-x-1')} /></button></div></div></section></div><section className="mt-5 grid gap-4 sm:grid-cols-3"><MiniSummary icon={<FileArchive size={17} />} label="Document types" value={documents.length} action="Manage types" onClick={() => setLocation('/documents')} /><MiniSummary icon={<Upload size={17} />} label="Pending uploads" value={uploads.filter(x => x.status !== 'Indexed').length} action="Review uploads" onClick={() => setLocation('/upload')} /><MiniSummary icon={<ShieldCheck size={17} />} label="Indexed records" value={uploads.filter(x => x.status === 'Indexed').length} action="Open activity" onClick={() => setLocation('/activity')} /></section></div>;
}

function Folders({ folders, setFolders, addActivity, setLocation, role }: { folders: StudentFolder[]; setFolders: (v: StudentFolder[]) => void; addActivity: (action: string, subject: string, metadata?: { folder?: string; document?: string }) => void; setLocation: (path: string) => void; role: UserRole }) {
  const [query, setQuery] = useState(''); const [sort, setSort] = useState('Recently updated'); const [selected, setSelected] = useState<StudentFolder | null>(null);
  const visible = useMemo(() => folders.filter(f => `${f.studentName} ${f.studentId}`.toLowerCase().includes(query.toLowerCase())).sort((a, b) => sort === 'Name A–Z' ? a.studentName.localeCompare(b.studentName) : new Date(b.lastUpdated).getTime() - new Date(a.lastUpdated).getTime()), [folders, query, sort]);
  return <div className="mx-auto max-w-[1420px] p-5 sm:p-7"><PageHeader eyebrow="Archive management" title="Student Folders" description="Browse and review student records held in the archive." actions={<Button onClick={() => setLocation('/upload')}><Plus size={14} />Add document</Button>} /><div className="surface-card rounded-lg"><div className="flex flex-col gap-3 border-b border-[#e8ebef] p-4 lg:flex-row lg:items-center"><div className="relative flex-1"><Search size={15} className="absolute left-3 top-2.5 text-[#8a97a7]" /><input data-testid="input-search-folders" value={query} onChange={e => setQuery(e.target.value)} placeholder="Search by student name or ID" className="h-9 w-full rounded-md border border-[#d9dfe7] pl-9 pr-3 text-xs outline-none focus:border-[#5688bd]" /></div><select data-testid="select-folder-sort" value={sort} onChange={e => setSort(e.target.value)} className="h-9 rounded-md border border-[#d9dfe7] bg-white px-3 text-xs text-[#47576b]"><option>Recently updated</option><option>Name A–Z</option></select></div><div className="overflow-x-auto"><table className="w-full min-w-[620px] text-left"><thead><tr className="border-b border-[#e8ebef] bg-[#fafbfc] text-[10px] uppercase tracking-[.1em] text-[#8a96a5]"><th className="px-5 py-3 font-bold">Student</th><th className="px-4 py-3 font-bold">Documents</th><th className="px-4 py-3 font-bold">Last updated</th><th className="px-5 py-3" /></tr></thead><tbody className="divide-y divide-[#edf0f3]">{visible.map(folder => <tr data-testid={`row-folder-${folder.id}`} key={folder.id} className="group hover:bg-[#fbfcfd]"><td className="px-5 py-3.5"><div className="flex items-center gap-3"><div className="flex h-8 w-8 items-center justify-center rounded-md bg-[#eaf0f7] text-[10px] font-bold text-[#315c87]">{folder.studentName.split(' ').map(x => x[0]).slice(0, 2).join('')}</div><div><div className="text-xs font-bold text-[#263950]">{folder.studentName}</div><div className="mono mt-0.5 text-[10px] text-[#8995a4]">{folder.studentId}</div></div></div></td><td className="px-4 py-3.5 text-xs font-semibold text-[#3f5065]">{folder.documentCount} <span className="font-normal text-[#9aa3ae]">files</span></td><td className="px-4 py-3.5 text-xs text-[#718096]">{formatDate(folder.lastUpdated)}</td><td className="px-5 py-3.5 text-right"><Button variant="ghost" onClick={() => { setSelected(folder); addActivity('Viewed folder', folder.studentName, { folder: folder.studentName }); }} className="px-2" testId={`button-view-folder-${folder.id}`}><Eye size={14} /></Button></td></tr>)}</tbody></table>{!visible.length && <EmptyState icon={FolderOpen} title="No folders found" body="Try adjusting your search." />}</div><div className="flex items-center justify-between border-t border-[#e8ebef] px-5 py-3 text-[10px] text-[#8a95a5]"><span>Showing {visible.length} of {folders.length} folders</span></div></div>{selected && <FolderDrawer folder={selected} onClose={() => setSelected(null)} onUpdate={folder => { setFolders(folders.map(f => f.id === folder.id ? folder : f)); setSelected(folder); }} />}</div>;
}

function ReadOnlyFolders({ folders, addActivity, title = 'Student folders' }: { folders: StudentFolder[]; addActivity: (action: string, subject: string, metadata?: { folder?: string; document?: string }) => void; title?: string }) {
  const [query, setQuery] = useState(''); const [selected, setSelected] = useState<StudentFolder | null>(null);
  const visible = folders.filter(folder => `${folder.studentName} ${folder.studentId}`.toLowerCase().includes(query.toLowerCase()));
  return <div className="mx-auto max-w-[1420px] p-5 sm:p-7"><PageHeader eyebrow="Records lookup" title={title} description="Open student records to view and print documents." /><div className="surface-card rounded-lg"><div className="border-b border-[#e8ebef] p-4"><div className="relative max-w-xl"><Search size={15} className="absolute left-3 top-2.5 text-[#8a97a7]" /><input data-testid="input-search-records" value={query} onChange={e => setQuery(e.target.value)} placeholder="Search by Student ID or student name" className="h-9 w-full rounded-md border border-[#d9dfe7] pl-9 pr-3 text-xs outline-none focus:border-[#5688bd]" /></div></div><div className="divide-y divide-[#edf0f3]">{visible.map(folder => <button key={folder.id} data-testid={`readonly-folder-${folder.id}`} onClick={() => { setSelected(folder); addActivity('Viewed folder', folder.studentName, { folder: folder.studentName }); }} className="flex w-full items-center gap-4 px-5 py-4 text-left hover:bg-[#fbfcfd]"><div className="flex h-9 w-9 items-center justify-center rounded-md bg-[#eaf0f7] text-[10px] font-bold text-[#315c87]">{folder.studentName.split(' ').map(x => x[0]).slice(0, 2).join('')}</div><div className="flex-1"><div className="text-xs font-bold text-[#263950]">{folder.studentName}</div><div className="mono mt-1 text-[10px] text-[#8995a4]">{folder.studentId}</div></div><span className="text-xs text-[#718096]">{folder.documentCount} files</span><ChevronRight size={15} className="text-[#9aa4b1]" /></button>)}{!visible.length && <EmptyState icon={FolderOpen} title="No student records found" body="Try a different Student ID or name." />}</div></div>{selected && <ReadOnlyFolderViewer folder={selected} onClose={() => setSelected(null)} onActivity={addActivity} />}</div>;
}

function ReadOnlyFolderViewer({ folder, onClose, onActivity }: { folder: StudentFolder; onClose: () => void; onActivity: (action: string, subject: string, metadata?: { folder?: string; document?: string }) => void }) {
  const documents = ['Transcript of Records', 'Student Permanent Record', 'Government ID', 'Certificate of Graduation'].slice(0, Math.min(4, folder.documentCount)); const [document, setDocument] = useState<string | null>(null);
  return <div className="fixed inset-0 z-40 bg-[#0f1b2d]/35" onMouseDown={e => { if (e.target === e.currentTarget) onClose(); }}><div className="slide-in absolute right-0 top-0 h-full w-full max-w-[470px] overflow-y-auto bg-white shadow-2xl"><div className="flex items-center justify-between border-b border-[#e7eaf0] px-6 py-5"><div><div className="label-caps">Student record</div><h2 className="mt-1 text-lg font-bold text-[#182a43]">{folder.studentName}</h2><div className="mono mt-1 text-[10px] text-[#8995a4]">{folder.studentId}</div></div><button onClick={onClose} className="rounded p-1.5 text-[#8a95a5] hover:bg-[#f1f4f7]"><X size={18} /></button></div><div className="space-y-5 p-6"><div><div className="label-caps mb-2">Documents</div><div className="space-y-2">{documents.map(name => <button key={name} onClick={() => { setDocument(name); onActivity('Viewed document', name, { folder: folder.studentName, document: name }); }} className="flex w-full items-center gap-2 rounded-md border border-[#edf0f3] px-3 py-3 text-left hover:border-[#b9cbe0]"><FileCheck2 size={14} className="text-[#2b9b72]" /><span className="flex-1 text-xs text-[#4a5b70]">{name}</span><Eye size={14} className="text-[#6d839d]" /></button>)}</div></div>{document && <div className="rounded-lg border border-[#dce5ee] bg-[#f8fafc] p-4"><div className="label-caps">Document viewer</div><div className="mt-2 text-xs font-bold text-[#263950]">{document}</div><div className="mt-2 h-28 rounded border border-dashed border-[#c9d5e1] bg-white p-4 text-center text-[11px] text-[#8492a3]">Document preview available for viewing and printing.</div><Button className="mt-3 w-full" onClick={() => { onActivity('Printed document', document, { folder: folder.studentName, document }); window.print(); }}><Printer size={14} />Print document</Button></div>}</div></div></div>;
}

function FolderDrawer({ folder, onClose, onUpdate }: { folder: StudentFolder; onClose: () => void; onUpdate: (folder: StudentFolder) => void }) {
  return <div className="fixed inset-0 z-40 bg-[#0f1b2d]/35" onMouseDown={e => { if (e.target === e.currentTarget) onClose(); }}><div className="slide-in absolute right-0 top-0 h-full w-full max-w-[430px] overflow-y-auto bg-white shadow-2xl"><div className="flex items-center justify-between border-b border-[#e7eaf0] px-6 py-5"><div><div className="label-caps">Student record</div><h2 className="mt-1 text-lg font-bold text-[#182a43]">{folder.studentName}</h2><div className="mono mt-1 text-[10px] text-[#8995a4]">{folder.studentId}</div></div><button data-testid="button-close-folder-drawer" onClick={onClose} className="rounded p-1.5 text-[#8a95a5] hover:bg-[#f1f4f7]"><X size={18} /></button></div><div className="space-y-6 p-6"><div className="grid grid-cols-2 gap-3"><div className="rounded-md border border-[#e7ebef] p-3"><div className="label-caps">Documents</div><div className="mt-2 text-xl font-bold text-[#263950]">{folder.documentCount}</div></div><div className="rounded-md border border-[#e7ebef] p-3"><div className="label-caps">Last updated</div><div className="mt-2 text-xs font-bold text-[#263950]">{formatDate(folder.lastUpdated)}</div></div></div><div><div className="label-caps mb-2">Document inventory</div><div className="space-y-2">{['Transcript of Records', 'Student Permanent Record', 'Government ID', 'Certificate of Graduation'].slice(0, Math.min(4, folder.documentCount)).map(name => <div className="flex items-center gap-2 rounded-md border border-[#edf0f3] px-3 py-2.5" key={name}><FileCheck2 size={14} className="text-[#2b9b72]" /><span className="flex-1 text-xs text-[#4a5b70]">{name}</span><span className="text-[10px] text-[#9aa4b1]">Indexed</span></div>)}</div></div><Button className="w-full" onClick={() => onUpdate({ ...folder, lastUpdated: new Date().toISOString() })} testId="button-save-folder">Save folder details</Button></div></div></div>;
}

function Documents({ documents, setDocuments, addActivity }: { documents: DocumentType[]; setDocuments: (v: DocumentType[]) => void; addActivity: (action: string, subject: string) => void }) {
  const [query, setQuery] = useState(''); const [category, setCategory] = useState('All categories'); const [status, setStatus] = useState('All statuses'); const [page, setPage] = useState(1); const [modal, setModal] = useState<'add' | 'edit' | null>(null); const [editing, setEditing] = useState<DocumentType | null>(null); const [confirm, setConfirm] = useState<{ kind: 'toggle' | 'delete'; doc: DocumentType } | null>(null);
  const filtered = documents.filter(d => (category === 'All categories' || d.category === category) && (status === 'All statuses' || d.status === status) && `${d.name} ${d.description}`.toLowerCase().includes(query.toLowerCase()));
  const pageCount = Math.max(1, Math.ceil(filtered.length / 5)); const activePage = Math.min(page, pageCount); const paged = filtered.slice((activePage - 1) * 5, activePage * 5);
  const openAdd = () => { setEditing(null); setModal('add'); }; const openEdit = (doc: DocumentType) => { setEditing(doc); setModal('edit'); };
  const save = (doc: DocumentType) => { if (editing) { setDocuments(documents.map(item => item.id === doc.id ? doc : item)); addActivity('Updated document type', doc.name); } else { setDocuments([...documents, doc]); addActivity('Added document type', doc.name); } setModal(null); };
  return <div className="mx-auto max-w-[1420px] p-5 sm:p-7"><PageHeader eyebrow="Archive management" title="Document Types" description="Manage the record categories accepted by the registrar archive." actions={<Button onClick={openAdd} testId="button-add-document-type"><Plus size={14} />Add document type</Button>} /><div className="surface-card rounded-lg"><div className="flex flex-col gap-3 border-b border-[#e8ebef] p-4 lg:flex-row lg:items-center"><div className="relative flex-1"><Search size={15} className="absolute left-3 top-2.5 text-[#8a97a7]" /><input data-testid="input-search-document-types" value={query} onChange={e => { setQuery(e.target.value); setPage(1); }} placeholder="Search document types" className="h-9 w-full rounded-md border border-[#d9dfe7] pl-9 pr-3 text-xs outline-none focus:border-[#5688bd]" /></div><select data-testid="select-document-category" value={category} onChange={e => { setCategory(e.target.value); setPage(1); }} className="h-9 rounded-md border border-[#d9dfe7] bg-white px-3 text-xs text-[#47576b]"><option>All categories</option><option>Academic</option><option>Administrative</option><option>Identity</option></select><select data-testid="select-document-status" value={status} onChange={e => { setStatus(e.target.value); setPage(1); }} className="h-9 rounded-md border border-[#d9dfe7] bg-white px-3 text-xs text-[#47576b]"><option>All statuses</option><option>Active</option><option>Inactive</option></select></div><div className="divide-y divide-[#edf0f3]">{paged.map(doc => <div data-testid={`row-document-type-${doc.id}`} key={doc.id} className="flex flex-col gap-3 px-5 py-4 sm:flex-row sm:items-center"><div className="flex min-w-0 flex-1 items-center gap-3"><div className="rounded-md bg-[#edf2f7] p-2.5 text-[#587391]"><FileText size={16} /></div><div className="min-w-0"><div className="text-sm font-bold text-[#273a51]">{doc.name}</div><div className="mt-1 truncate text-xs text-[#8290a1]">{doc.description}</div></div></div><div className="flex items-center gap-5 sm:w-[390px] sm:justify-end"><span className="rounded bg-[#f0f3f7] px-2 py-1 text-[10px] font-bold text-[#65758a]">{doc.category}</span><span className="text-[11px] text-[#8691a0]">{formatDate(doc.dateAdded)}</span><StatusPill status={doc.status} /><div className="flex gap-1"><button data-testid={`button-edit-document-${doc.id}`} onClick={() => openEdit(doc)} className="rounded p-1.5 text-[#6b7b8f] hover:bg-[#edf2f7] hover:text-[#24558d]"><Pencil size={14} /></button><button data-testid={`button-toggle-document-${doc.id}`} onClick={() => setConfirm({ kind: 'toggle', doc })} className="rounded p-1.5 text-[#6b7b8f] hover:bg-[#edf2f7] hover:text-[#24558d]"><MoreHorizontal size={14} /></button><button data-testid={`button-delete-document-${doc.id}`} onClick={() => setConfirm({ kind: 'delete', doc })} className="rounded p-1.5 text-[#9b6c6a] hover:bg-[#fceceb] hover:text-[#b94843]"><Trash2 size={14} /></button></div></div></div>)}{!filtered.length && <EmptyState icon={FileText} title="No document types found" body="Add a type or change your filters to see results." />}</div><div className="flex items-center justify-between border-t border-[#e8ebef] px-5 py-3 text-[10px] text-[#8a95a5]"><span>Showing {paged.length} of {filtered.length} filtered · {documents.length} total</span><div className="flex items-center gap-2"><span>Page {activePage} of {pageCount}</span><button data-testid="button-documents-prev" disabled={activePage === 1} onClick={() => setPage(Math.max(1, activePage - 1))} className="rounded border border-[#e0e5eb] p-1.5 text-[#6b7b8f] disabled:opacity-40"><ChevronLeft size={13} /></button><button data-testid="button-documents-next" disabled={activePage === pageCount} onClick={() => setPage(Math.min(pageCount, activePage + 1))} className="rounded border border-[#e0e5eb] p-1.5 text-[#6b7b8f] disabled:opacity-40"><ChevronRight size={13} /></button></div></div></div>{modal && <DocumentModal document={editing} onClose={() => setModal(null)} onSave={save} />}{confirm && <Modal title={confirm.kind === 'delete' ? 'Delete document type?' : confirm.doc.status === 'Active' ? 'Deactivate document type?' : 'Activate document type?'} onClose={() => setConfirm(null)} width="max-w-md"><div className="p-6"><p className="text-sm leading-6 text-[#617084]">{confirm.kind === 'delete' ? <>This will permanently remove <strong className="text-[#273a51]">{confirm.doc.name}</strong> from the archive configuration.</> : <>You are about to {confirm.doc.status === 'Active' ? 'deactivate' : 'activate'} <strong className="text-[#273a51]">{confirm.doc.name}</strong>. {confirm.doc.status === 'Active' ? 'It will no longer be available for new uploads.' : 'It will become available for new uploads.'}</>}</p><div className="mt-6 flex justify-end gap-2"><Button variant="secondary" onClick={() => setConfirm(null)}>Cancel</Button><Button variant={confirm.kind === 'delete' ? 'danger' : 'primary'} onClick={() => { if (confirm.kind === 'delete') { setDocuments(documents.filter(d => d.id !== confirm.doc.id)); addActivity('Deleted document type', confirm.doc.name); } else { const next = { ...confirm.doc, status: confirm.doc.status === 'Active' ? 'Inactive' as DocumentStatus : 'Active' as DocumentStatus }; setDocuments(documents.map(d => d.id === next.id ? next : d)); addActivity(next.status === 'Active' ? 'Activated document type' : 'Deactivated document type', next.name); } setConfirm(null); }}>Confirm</Button></div></div></Modal>}</div>;
}
function DocumentModal({ document, onClose, onSave }: { document: DocumentType | null; onClose: () => void; onSave: (doc: DocumentType) => void }) {
  const [name, setName] = useState(document?.name ?? ''); const [description, setDescription] = useState(document?.description ?? ''); const [category, setCategory] = useState<DocumentCategory>(document?.category ?? 'Academic'); const [status, setStatus] = useState<DocumentStatus>(document?.status ?? 'Active');
  return <Modal title={document ? 'Edit document type' : 'Add document type'} onClose={onClose}><form className="space-y-4 p-6" onSubmit={e => { e.preventDefault(); if (name.trim()) onSave({ id: document?.id ?? `dt-${Date.now()}`, name: name.trim(), description, category, status, dateAdded: document?.dateAdded ?? new Date().toISOString().slice(0, 10) }); }}><Field label="Document type name" value={name} onChange={setName} placeholder="e.g. Clearance Form" required /><label className="block space-y-1.5"><span className="label-caps text-[10px]">Description</span><textarea data-testid="input-document-description" value={description} onChange={e => setDescription(e.target.value)} rows={3} placeholder="Describe what this record contains" className="w-full resize-none rounded-md border border-[#d9dfe7] px-3 py-2 text-sm outline-none focus:border-[#5688bd]" /></label><div className="grid gap-4 sm:grid-cols-2"><label className="block space-y-1.5"><span className="label-caps text-[10px]">Category</span><select data-testid="select-modal-category" value={category} onChange={e => setCategory(e.target.value as DocumentCategory)} className="h-10 w-full rounded-md border border-[#d9dfe7] bg-white px-3 text-xs"><option>Academic</option><option>Administrative</option><option>Identity</option></select></label><label className="block space-y-1.5"><span className="label-caps text-[10px]">Status</span><select data-testid="select-modal-status" value={status} onChange={e => setStatus(e.target.value as DocumentStatus)} className="h-10 w-full rounded-md border border-[#d9dfe7] bg-white px-3 text-xs"><option>Active</option><option>Inactive</option></select></label></div><div className="flex justify-end gap-2 border-t border-[#edf0f3] pt-5"><Button variant="secondary" onClick={onClose}>Cancel</Button><Button type="submit" testId="button-save-document-type">{document ? 'Save changes' : 'Add document type'}</Button></div></form></Modal>;
}

function UploadPage({ uploads, setUploads, addActivity, documents, archiveActive }: { uploads: UploadRecord[]; setUploads: (v: UploadRecord[]) => void; addActivity: (action: string, subject: string) => void; documents: DocumentType[]; archiveActive: boolean }) {
  const [dragging, setDragging] = useState(false); const [file, setFile] = useState<File | null>(null); const [docType, setDocType] = useState(documents[0]?.name ?? ''); const [student, setStudent] = useState(''); const [progress, setProgress] = useState(0); const [success, setSuccess] = useState(false); const [notice, setNotice] = useState('');
  const handleFile = (next: File | undefined) => { if (next) { setFile(next); setSuccess(false); setNotice(''); } };
  const submit = (e: React.FormEvent) => { e.preventDefault(); if (!archiveActive) { setNotice('Archive uploads are paused. Activate the archive in Settings to continue.'); return; } if (!file || !student || !docType) { setNotice('Choose a file and complete the metadata fields.'); return; } setProgress(25); window.setTimeout(() => setProgress(70), 200); window.setTimeout(() => { const item: UploadRecord = { id: `up-${Date.now()}`, fileName: file.name, documentType: docType, studentName: student, uploadedAt: new Date().toISOString(), status: 'Indexed' }; setUploads([item, ...uploads]); addActivity('Uploaded document', file.name); setProgress(100); setSuccess(true); setFile(null); setStudent(''); }, 650); };
  return <div className="mx-auto max-w-[1420px] p-5 sm:p-7"><PageHeader eyebrow="Archive management" title="Upload Documents" description="Add a verified record to an existing student folder." actions={<StatusPill status={archiveActive ? 'Active' : 'Paused'} />} /><div className="grid gap-5 xl:grid-cols-[1.05fr_.95fr]"><section className="surface-card rounded-lg p-5 sm:p-6"><form onSubmit={submit} className="space-y-5"><div onDragOver={e => { e.preventDefault(); setDragging(true); }} onDragLeave={() => setDragging(false)} onDrop={e => { e.preventDefault(); setDragging(false); handleFile(e.dataTransfer.files[0]); }} className={cx('rounded-lg border-2 border-dashed p-8 text-center transition', dragging ? 'border-[#5688bd] bg-[#edf4fb]' : 'border-[#ccd5df] bg-[#fafbfc]')}><input data-testid="input-upload-file" id="upload-file" type="file" className="hidden" accept=".pdf,.jpg,.jpeg,.png,.doc,.docx" onChange={e => handleFile(e.target.files?.[0])} /><label htmlFor="upload-file" className="cursor-pointer"><div className="mx-auto mb-3 flex h-11 w-11 items-center justify-center rounded-full bg-[#eaf0f7] text-[#4f7398]"><Upload size={20} /></div><div className="text-sm font-bold text-[#34445a]">{file ? file.name : 'Drop a file here, or browse'}</div><div className="mt-1 text-xs text-[#8a96a5]">PDF, JPG, PNG, DOC up to 25 MB</div></label></div><div className="grid gap-4 sm:grid-cols-2"><label className="block space-y-1.5"><span className="label-caps text-[10px]">Document type<span className="ml-1 text-[#b94843]">*</span></span><select data-testid="select-upload-document-type" value={docType} onChange={e => setDocType(e.target.value)} className="h-10 w-full rounded-md border border-[#d9dfe7] bg-white px-3 text-xs"><option value="">Select document type</option>{documents.filter(d => d.status === 'Active').map(d => <option key={d.id}>{d.name}</option>)}</select></label><Field label="Student name" value={student} onChange={setStudent} placeholder="Search or enter student name" required /></div><div className="rounded-md bg-[#f5f7f9] p-3 text-[11px] leading-5 text-[#718096]"><strong className="text-[#52647a]">Before you upload:</strong> Check that the document is legible, belongs to the selected student, and has not already been indexed.</div>{notice && <div data-testid="text-upload-notice" className="rounded-md bg-[#fff6df] px-3 py-2 text-xs text-[#89691f]">{notice}</div>}{progress > 0 && <div><div className="mb-1 flex justify-between text-[10px] text-[#758397]"><span>{progress === 100 ? 'Upload complete' : 'Uploading and indexing...'}</span><span>{progress}%</span></div><div className="h-1.5 overflow-hidden rounded-full bg-[#e6ebf0]"><div className="h-full rounded-full bg-[#2b9b72] transition-all duration-500" style={{ width: `${progress}%` }} /></div></div>}{success && <div data-testid="text-upload-success" className="flex items-center gap-2 rounded-md bg-[#e7f6ef] px-3 py-2.5 text-xs font-semibold text-[#277854]"><Check size={15} />Document indexed successfully.</div>}<div className="flex justify-end"><Button type="submit" disabled={progress > 0 && progress < 100} testId="button-submit-upload"><Upload size={14} />Upload and index</Button></div></form></section><section className="surface-card rounded-lg"><div className="border-b border-[#e8ebef] px-5 py-4"><h2 className="text-sm font-bold text-[#1c2f47]">Recent uploads</h2><p className="mt-0.5 text-[11px] text-[#8a95a5]">Most recent files added to the archive.</p></div><div className="divide-y divide-[#edf0f3]">{uploads.slice(0, 6).map(item => <div data-testid={`upload-row-${item.id}`} key={item.id} className="flex items-start gap-3 px-5 py-4"><div className="rounded-md bg-[#edf2f7] p-2 text-[#597794]"><File size={16} /></div><div className="min-w-0 flex-1"><div className="truncate text-xs font-bold text-[#34445a]">{item.fileName}</div><div className="mt-1 text-[10px] text-[#8a96a5]">{item.studentName} · {item.documentType}</div><div className="mt-2 flex items-center justify-between"><StatusPill status={item.status} /><span className="text-[10px] text-[#9aa4b1]">{formatRelative(item.uploadedAt)}</span></div></div></div>)}{!uploads.length && <EmptyState icon={Upload} title="No uploads yet" body="Files you index will be listed here." />}</div></section></div></div>;
}

type ScanDocument = { id: string; fileName: string; label: string; student: string; source: 'Camera' | 'Scanner' | 'Computer file' };

function ScanWizard({ uploads, setUploads, folders, setFolders, addActivity, documents, archiveActive }: { uploads: UploadRecord[]; setUploads: (v: UploadRecord[]) => void; folders: StudentFolder[]; setFolders: (v: StudentFolder[]) => void; addActivity: (action: string, subject: string, metadata?: { folder?: string; document?: string }) => void; documents: DocumentType[]; archiveActive: boolean }) {
  const [step, setStep] = useState(1); const [mode, setMode] = useState<'Student Scan' | 'General Scan'>('Student Scan'); const [studentId, setStudentId] = useState(''); const [studentName, setStudentName] = useState(''); const [currentStudent, setCurrentStudent] = useState(''); const [docType, setDocType] = useState(documents.find(item => item.status === 'Active')?.name ?? ''); const [draft, setDraft] = useState<ScanDocument | null>(null); const [scanDocs, setScanDocs] = useState<ScanDocument[]>([]); const [cameraOpen, setCameraOpen] = useState(false); const [notice, setNotice] = useState(''); const [complete, setComplete] = useState(false); const videoRef = useRef<HTMLVideoElement>(null); const canvasRef = useRef<HTMLCanvasElement>(null); const streamRef = useRef<MediaStream | null>(null);
  useEffect(() => () => streamRef.current?.getTracks().forEach(track => track.stop()), []);
  useEffect(() => { if (!cameraOpen) return; navigator.mediaDevices?.getUserMedia({ video: { facingMode: 'environment' }, audio: false }).then(stream => { streamRef.current = stream; if (videoRef.current) videoRef.current.srcObject = stream; }).catch(() => setNotice('Camera access was unavailable. Allow camera permission or use a computer file.')); return () => streamRef.current?.getTracks().forEach(track => track.stop()); }, [cameraOpen]);
  const activeTypes = documents.filter(item => item.status === 'Active');
  const addFile = (file: File, source: ScanDocument['source']) => { const valid = ['application/pdf', 'image/jpeg', 'image/png'].includes(file.type) || /\.(pdf|jpe?g|png)$/i.test(file.name); if (!valid) { setNotice('Only PNG, JPG/JPEG, and PDF files can be archived.'); return; } setDraft({ id: `scan-${Date.now()}`, fileName: file.name, label: docType, student: mode === 'Student Scan' ? `${studentName} · ${studentId}` : currentStudent, source }); setNotice(''); };
  const capture = () => { const video = videoRef.current; const canvas = canvasRef.current; if (!video || !canvas) return; canvas.width = video.videoWidth || 1280; canvas.height = video.videoHeight || 720; canvas.getContext('2d')?.drawImage(video, 0, 0, canvas.width, canvas.height); canvas.toBlob(blob => { if (blob) addFile(new window.File([blob], `camera-scan-${Date.now()}.jpg`, { type: 'image/jpeg' }), 'Camera'); setCameraOpen(false); }, 'image/jpeg', 0.92); };
  const continueToFiles = () => { if (mode === 'Student Scan' && (!studentName.trim() || !studentId.trim())) { setNotice('Identify the student with both Student ID and name before adding documents.'); return; } setNotice(''); setStep(3); };
  const addDraft = () => { if (!draft) { setNotice('Add a document from camera, scanner, or computer file first.'); return; } if (mode === 'General Scan' && !currentStudent.trim()) { setNotice('Assign this document to a student before adding it.'); return; } setScanDocs(previous => [...previous, { ...draft, student: mode === 'Student Scan' ? `${studentName} · ${studentId}` : currentStudent }]); setDraft(null); setNotice('Document added to this scan batch.'); };
  const archiveBatch = async () => { if (!archiveActive) { setNotice('Archive uploads are paused. Activate the archive in Settings to continue.'); return; } if (!scanDocs.length || (mode === 'General Scan' && scanDocs.some(item => !item.student.trim()))) { setNotice('Every document must have a student assignment before archiving.'); return; } const response = await fetch('/api/admin/archive', { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ documents: scanDocs.map(item => ({ fileName: item.fileName, student: item.student, label: item.label })), destination: '/Users/registrar/Documents/adzu-archive' }) }); if (!response.ok) { setNotice('The server rejected this archive action. Confirm that the session is an Admin session.'); return; } const timestamp = new Date().toISOString(); const nextFolders = [...folders]; scanDocs.forEach(item => { const [studentNamePart, studentIdPart] = item.student.split(' · '); const existing = nextFolders.find(folder => folder.studentId === studentIdPart || folder.studentName === studentNamePart); if (existing) { existing.documentCount += 1; existing.lastUpdated = timestamp; existing.status = 'In Progress'; } else { nextFolders.unshift({ id: `folder-${Date.now()}-${item.id}`, studentId: studentIdPart || item.student, studentName: studentNamePart || item.student, program: 'Not specified', documentCount: 1, status: 'In Progress', lastUpdated: timestamp }); } }); setFolders(nextFolders); setUploads([...scanDocs.map(item => ({ id: item.id, fileName: item.fileName, documentType: item.label, studentName: item.student, uploadedAt: timestamp, status: 'Indexed' as const })), ...uploads]); scanDocs.forEach(item => addActivity('Archived document', item.fileName, { folder: item.student, document: item.label })); setComplete(true); setStep(6); };
  const stepLabels = ['Scan type', 'Identify students', 'Add documents', 'Label & review', 'Destination', 'Complete'];
  return <div className="mx-auto max-w-[1420px] p-5 sm:p-7"><PageHeader eyebrow="Archive intake" title="Scan and archive documents" description="Admin workflow for student scans and mixed general scans." actions={<StatusPill status={archiveActive ? 'Active' : 'Paused'} />} /><div className="surface-card mb-5 overflow-hidden rounded-lg"><div className="grid grid-cols-2 border-b border-[#e8ebef] md:grid-cols-6">{stepLabels.map((label, index) => <div key={label} className={cx('border-r border-[#edf0f3] px-3 py-3 text-center text-[10px] font-bold', step === index + 1 ? 'bg-[#edf4fb] text-[#24558d]' : step > index + 1 ? 'text-[#2b9b72]' : 'text-[#98a1ad')}><span className="mr-1">{index + 1}.</span>{label}</div>)}</div><div className="p-5 sm:p-7">{step === 1 && <div className="mx-auto max-w-2xl"><div className="label-caps">Choose scan type</div><div className="mt-4 grid gap-4 sm:grid-cols-2"><button data-testid="button-student-scan" onClick={() => setMode('Student Scan')} className={cx('rounded-lg border p-5 text-left', mode === 'Student Scan' ? 'border-[#5688bd] bg-[#edf4fb]' : 'border-[#dce3eb]')}><FolderOpen size={22} className="text-[#315c87]" /><div className="mt-3 text-sm font-bold text-[#263950]">Student Scan</div><div className="mt-1 text-xs text-[#718096]">All documents belong to one identified student.</div></button><button data-testid="button-general-scan" onClick={() => setMode('General Scan')} className={cx('rounded-lg border p-5 text-left', mode === 'General Scan' ? 'border-[#5688bd] bg-[#edf4fb]' : 'border-[#dce3eb]')}><ScanLine size={22} className="text-[#315c87]" /><div className="mt-3 text-sm font-bold text-[#263950]">General Scan</div><div className="mt-1 text-xs text-[#718096]">Assign each scanned document to its own student folder.</div></button></div><div className="mt-6 flex justify-end"><Button onClick={() => setStep(2)}>Continue <ChevronRight size={14} /></Button></div></div>}{step === 2 && <div className="mx-auto max-w-2xl">{mode === 'Student Scan' ? <div className="grid gap-4 sm:grid-cols-2"><Field label="Student ID" value={studentId} onChange={setStudentId} placeholder="e.g. 2022-01764" required /><Field label="Student name" value={studentName} onChange={setStudentName} placeholder="Search student name" required /></div> : <div className="rounded-md bg-[#f4f7fa] p-4 text-xs text-[#617084]">General Scan selected. You will assign a student to each document in the next step.</div>}{notice && <div className="mt-4 rounded-md bg-[#fff6df] px-3 py-2 text-xs text-[#89691f]">{notice}</div>}<div className="mt-6 flex justify-between"><Button variant="secondary" onClick={() => setStep(1)}>Back</Button><Button onClick={continueToFiles}>Continue <ChevronRight size={14} /></Button></div></div>}{step === 3 && <div><div className="grid gap-5 lg:grid-cols-[1fr_1fr]"><div className="rounded-lg border border-[#e1e7ee] p-5"><div className="label-caps">Add from source</div><div className="mt-4 grid grid-cols-3 gap-2"><button onClick={() => setCameraOpen(true)} className="rounded-md border border-[#d9e1ea] p-3 text-xs font-bold text-[#40556e] hover:bg-[#f4f7fa]"><Camera size={17} className="mx-auto mb-2 text-[#315c87]" />Camera</button><label className="cursor-pointer rounded-md border border-[#d9e1ea] p-3 text-center text-xs font-bold text-[#40556e] hover:bg-[#f4f7fa]"><input className="hidden" type="file" accept=".pdf,.jpg,.jpeg,.png" onChange={e => e.target.files?.[0] && addFile(e.target.files[0], 'Scanner')} /><ScanLine size={17} className="mx-auto mb-2 text-[#315c87]" />Scanner</label><label className="cursor-pointer rounded-md border border-[#d9e1ea] p-3 text-center text-xs font-bold text-[#40556e] hover:bg-[#f4f7fa]"><input className="hidden" type="file" accept=".pdf,.jpg,.jpeg,.png" onChange={e => e.target.files?.[0] && addFile(e.target.files[0], 'Computer file')} /><Upload size={17} className="mx-auto mb-2 text-[#315c87]" />Computer</label></div>{mode === 'General Scan' && <div className="mt-4"><Field label="Assign this document to student" value={currentStudent} onChange={setCurrentStudent} placeholder="Student ID · Student name" /></div>}<div className="mt-4 grid gap-3 sm:grid-cols-[1fr_auto]"><select value={docType} onChange={e => { setDocType(e.target.value); setDraft(draft ? { ...draft, label: e.target.value } : null); }} className="h-10 rounded-md border border-[#d9dfe7] bg-white px-3 text-xs">{activeTypes.map(item => <option key={item.id}>{item.name}</option>)}</select><Button variant="secondary" onClick={addDraft}><Plus size={14} />Add to batch</Button></div>{draft && <div className="mt-4 rounded-md bg-[#edf4fb] p-3 text-xs text-[#315c87]"><strong>{draft.fileName}</strong> ready to add · {draft.source}</div>}{notice && <div className="mt-4 rounded-md bg-[#fff6df] px-3 py-2 text-xs text-[#89691f]">{notice}</div>}</div><div className="rounded-lg border border-[#e1e7ee] p-5"><div className="flex items-center justify-between"><div className="label-caps">Batch documents</div><span className="text-[10px] text-[#8a96a5]">{scanDocs.length} added</span></div><div className="mt-3 space-y-2">{scanDocs.map(item => <div key={item.id} className="flex items-center gap-2 rounded-md border border-[#edf0f3] p-3"><FileCheck2 size={14} className="text-[#2b9b72]" /><div className="min-w-0 flex-1"><div className="truncate text-xs font-bold text-[#34445a]">{item.fileName}</div><div className="mt-1 text-[10px] text-[#8290a1]">{item.student} · {item.label}</div></div></div>)}{!scanDocs.length && <div className="py-10 text-center text-xs text-[#9aa4b1]">No documents added yet.</div>}</div></div></div><div className="mt-6 flex justify-between"><Button variant="secondary" onClick={() => setStep(2)}>Back</Button><Button onClick={() => { if (!scanDocs.length) { setNotice('Add at least one document to continue.'); return; } setStep(4); }}>Review labels <ChevronRight size={14} /></Button></div></div>}{step === 4 && <div><div className="label-caps">Label and review</div><div className="mt-3 overflow-hidden rounded-md border border-[#e1e7ee]">{scanDocs.map(item => <div key={item.id} className="flex flex-col gap-2 border-b border-[#edf0f3] p-4 last:border-0 sm:flex-row sm:items-center"><FileText size={16} className="text-[#597794]" /><div className="flex-1 text-xs font-bold text-[#34445a]">{item.fileName}<div className="mt-1 text-[10px] font-normal text-[#8290a1]">{item.student}</div></div><span className="rounded bg-[#f0f3f7] px-2 py-1 text-[10px] text-[#65758a]">{item.label}</span><span className="text-[10px] text-[#8a96a5]">{item.source}</span></div>)}</div><div className="mt-6 flex justify-between"><Button variant="secondary" onClick={() => setStep(3)}>Back</Button><Button onClick={() => setStep(5)}>Choose destination <ChevronRight size={14} /></Button></div></div>}{step === 5 && <div className="mx-auto max-w-2xl"><div className="rounded-lg border border-[#e1e7ee] p-5"><div className="label-caps">Archive destination</div><div className="mt-3 rounded-md bg-[#f4f7fa] p-4"><div className="text-xs font-bold text-[#34445a]">{mode === 'Student Scan' ? `${studentName} · ${studentId}` : `${scanDocs.length} student folders`}</div><div className="mono mt-1 text-[10px] text-[#8290a1]">/Users/registrar/Documents/adzu-archive</div></div><div className="mt-4 text-xs text-[#617084]">General Scan documents will remain separated by their student assignment. No documents will be combined into one folder.</div></div>{notice && <div className="mt-4 rounded-md bg-[#fff6df] px-3 py-2 text-xs text-[#89691f]">{notice}</div>}<div className="mt-6 flex justify-between"><Button variant="secondary" onClick={() => setStep(4)}>Back</Button><Button onClick={archiveBatch}><Archive size={14} />Archive batch</Button></div></div>}{step === 6 && <div className="mx-auto max-w-lg py-10 text-center"><div className="mx-auto flex h-14 w-14 items-center justify-center rounded-full bg-[#e5f5ee] text-[#2b9b72]"><Check size={28} /></div><h2 className="mt-4 text-lg font-bold text-[#263950]">Archive complete</h2><p className="mt-2 text-sm text-[#718096]">{scanDocs.length} document{scanDocs.length === 1 ? '' : 's'} indexed and assigned to the correct student folder{scanDocs.length === 1 ? '' : 's'}.</p><Button className="mt-6" onClick={() => { setStep(1); setScanDocs([]); setComplete(false); setStudentId(''); setStudentName(''); setCurrentStudent(''); }}>Start another scan</Button></div>}</div></div>{cameraOpen && <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#0f1b2d]/70 p-5"><div className="w-full max-w-2xl rounded-lg bg-white p-5 shadow-2xl"><div className="flex items-center justify-between"><div><div className="label-caps">Camera scan</div><h2 className="mt-1 text-lg font-bold text-[#263950]">Position the document in frame</h2></div><button onClick={() => setCameraOpen(false)}><X size={18} /></button></div><video ref={videoRef} autoPlay playsInline className="mt-4 aspect-video w-full rounded-md bg-[#101b2c] object-cover" /><canvas ref={canvasRef} className="hidden" /><div className="mt-4 flex justify-end gap-2"><Button variant="secondary" onClick={() => setCameraOpen(false)}><RefreshCw size={14} />Retake</Button><Button onClick={capture}><Camera size={14} />Capture and confirm</Button></div></div></div>}</div>;
}

function ActivityPage({ activity }: { activity: ActivityItem[] }) {
  const [query, setQuery] = useState(''); const [filter, setFilter] = useState('All activity'); const filtered = activity.filter(item => (filter === 'All activity' || item.action.toLowerCase().includes(filter.toLowerCase())) && `${item.action} ${item.subject} ${item.actor}`.toLowerCase().includes(query.toLowerCase()));
  return <div className="mx-auto max-w-[1000px] p-5 sm:p-7"><PageHeader eyebrow="Archive monitoring" title="Activity Log" description="A chronological record of actions taken across the e-Archive." actions={<Button variant="secondary" onClick={() => window.print()}><Download size={14} />Export log</Button>} /><div className="surface-card rounded-lg"><div className="flex flex-col gap-3 border-b border-[#e8ebef] p-4 sm:flex-row"><div className="relative flex-1"><Search size={15} className="absolute left-3 top-2.5 text-[#8a97a7]" /><input data-testid="input-search-activity" value={query} onChange={e => setQuery(e.target.value)} placeholder="Search activity" className="h-9 w-full rounded-md border border-[#d9dfe7] pl-9 text-xs outline-none focus:border-[#5688bd]" /></div><select data-testid="select-activity-filter" value={filter} onChange={e => setFilter(e.target.value)} className="h-9 rounded-md border border-[#d9dfe7] bg-white px-3 text-xs"><option>All activity</option><option>Uploaded</option><option>Updated</option><option>Added</option><option>Reviewed</option></select></div><div className="p-5 sm:p-7">{filtered.length ? <div className="relative ml-2 border-l border-[#dbe2e9]">{filtered.map(item => <div data-testid={`timeline-item-${item.id}`} key={item.id} className="relative pb-7 pl-7 last:pb-0"><span className="absolute -left-[7px] top-0 h-3 w-3 rounded-full border-2 border-white bg-[#2d649c] shadow-[0_0_0_1px_#b9c9d9]" /><div className="flex flex-col justify-between gap-1 sm:flex-row"><div className="text-sm text-[#33465e]"><strong className="font-bold">{item.action}</strong><span className="ml-1 text-[#697a8e]">{item.subject}</span></div><span className="text-[10px] text-[#97a1ad]">{formatRelative(item.timestamp)}</span></div><div className="mt-1.5 text-[11px] text-[#8995a4]">{item.actor} · {formatDate(item.timestamp)}</div></div>)}</div> : <EmptyState icon={Activity} title="No matching activity" body="Try a different search or activity filter." />}</div></div></div>;
}

function SettingsPage({ archiveActive, setArchiveActive, readOnly = false }: { archiveActive: boolean; setArchiveActive: (value: boolean) => void; readOnly?: boolean }) {
  const [notice, setNotice] = useState(''); const [retention, setRetention] = useState('Permanent'); const [autoIndex, setAutoIndex] = useState(true);
  const save = () => { setNotice('System settings saved locally.'); window.setTimeout(() => setNotice(''), 3000); };
  return <div className="mx-auto max-w-[1050px] p-5 sm:p-7"><PageHeader eyebrow="Administration" title="System Settings" description="Configure how the local e-Archive behaves on this workstation." /><div className="space-y-5"><section className="surface-card rounded-lg"><div className="border-b border-[#e8ebef] px-5 py-4"><h2 className="text-sm font-bold text-[#1c2f47]">Archive status</h2><p className="mt-0.5 text-[11px] text-[#8a95a5]">Control whether staff can add new records.</p></div><div className="flex items-center justify-between gap-4 p-5"><div className="flex items-center gap-3"><div className={cx('rounded-full p-2.5', archiveActive ? 'bg-[#e5f5ee] text-[#2b9b72]' : 'bg-[#fff6df] text-[#ae7d1e]')}>{archiveActive ? <CircleCheck size={18} /> : <CircleAlert size={18} />}</div><div><div className="text-sm font-bold text-[#34445a]">{archiveActive ? 'Archive is active' : 'Archive is paused'}</div><div className="mt-1 text-xs text-[#8591a0]">{archiveActive ? 'Uploads and indexing are available to authorized staff.' : 'New uploads are disabled until the archive is activated.'}</div></div></div><button data-testid="button-toggle-archive-settings" onClick={() => setArchiveActive(!archiveActive)} className={cx('relative h-7 w-12 rounded-full transition', archiveActive ? 'bg-[#2b9b72]' : 'bg-[#a9b4c0')}><span className={cx('absolute top-1 h-5 w-5 rounded-full bg-white shadow-sm transition-transform', archiveActive ? 'translate-x-6' : 'translate-x-1')} /></button></div></section><section className="surface-card rounded-lg"><div className="border-b border-[#e8ebef] px-5 py-4"><h2 className="text-sm font-bold text-[#1c2f47]">Document handling</h2><p className="mt-0.5 text-[11px] text-[#8a95a5]">Set the default behavior for indexed files.</p></div><div className="divide-y divide-[#edf0f3]"><div className="flex items-center justify-between gap-4 p-5"><div><div className="text-xs font-bold text-[#34445a]">Automatic indexing</div><div className="mt-1 text-[11px] text-[#8591a0]">Mark uploads as indexed after metadata is saved.</div></div><button data-testid="button-toggle-auto-index" onClick={() => setAutoIndex(!autoIndex)} className={cx('relative h-6 w-11 rounded-full', autoIndex ? 'bg-[#2b9b72]' : 'bg-[#a9b4c0]')}><span className={cx('absolute top-1 h-4 w-4 rounded-full bg-white shadow-sm transition-transform', autoIndex ? 'translate-x-6' : 'translate-x-1')} /></button></div><div className="flex items-center justify-between gap-4 p-5"><div><div className="text-xs font-bold text-[#34445a]">Record retention</div><div className="mt-1 text-[11px] text-[#8591a0]">How long files remain in the local archive.</div></div><select data-testid="select-retention" value={retention} onChange={e => setRetention(e.target.value)} className="h-9 rounded-md border border-[#d9dfe7] bg-white px-3 text-xs"><option>Permanent</option><option>25 years</option><option>10 years</option></select></div></div></section><section className="surface-card rounded-lg"><div className="flex flex-col justify-between gap-4 p-5 sm:flex-row sm:items-center"><div><div className="text-sm font-bold text-[#34445a]">Local archive location</div><div className="mono mt-2 rounded-md bg-[#f3f5f7] px-3 py-2 text-[10px] text-[#65758a]">/Users/registrar/Documents/adzu-archive</div></div><Button onClick={save} testId="button-save-settings"><Check size={14} />Save settings</Button></div></section>{notice && <div data-testid="text-settings-notice" className="rounded-md bg-[#e7f6ef] px-4 py-3 text-xs font-semibold text-[#277854]">{notice}</div>}</div></div>;
}

function LegacyAdminSettingsTabs({ archiveActive, setArchiveActive }: { archiveActive: boolean; setArchiveActive: (value: boolean) => void }) {
  const [tab, setTab] = useState<'folders' | 'location'>('folders'); const [format, setFormat] = useState('{Student ID} - {Student Name}'); const [uploadRequirements, setUploadRequirements] = useState('Student ID, student name, document type'); const [folderRequirements, setFolderRequirements] = useState('Student ID, student name, program'); const [destination, setDestination] = useState('/Users/registrar/Documents/adzu-archive'); const [notice, setNotice] = useState('');
  useEffect(() => { fetch('/api/archive/settings', { credentials: 'include' }).then(response => response.ok ? response.json() : null).then(settings => { if (!settings) return; setArchiveActive(settings.archiveActive); setDestination(settings.destination); setFormat(settings.folderNamingFormat ?? format); setUploadRequirements(settings.requiredUploadDetails ?? uploadRequirements); setFolderRequirements(settings.requiredFolderDetails ?? folderRequirements); }).catch(() => undefined); }, []);
  const save = async () => { const response = await fetch('/api/archive/settings', { method: 'PATCH', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ archiveActive, autoIndex: true, retention: 'Permanent', destination, folderNamingFormat: format, requiredUploadDetails: uploadRequirements, requiredFolderDetails: folderRequirements }) }); setNotice(response.ok ? 'Settings saved successfully.' : 'Settings could not be saved.'); window.setTimeout(() => setNotice(''), 3000); };
  return <div className="mx-auto max-w-[1050px] p-5 sm:p-7"><PageHeader eyebrow="Administration" title="System Settings" description="Configure folder rules, document requirements, and the archive location." /><div className="surface-card overflow-hidden rounded-lg"><div className="flex border-b border-[#e8ebef]"><button onClick={() => setTab('folders')} className={cx('px-5 py-4 text-xs font-bold', tab === 'folders' ? 'border-b-2 border-[#24558d] text-[#24558d]' : 'text-[#8a96a5]')}>Student Folder &amp; Document Settings</button><button onClick={() => setTab('location')} className={cx('px-5 py-4 text-xs font-bold', tab === 'location' ? 'border-b-2 border-[#24558d] text-[#24558d]' : 'text-[#8a96a5]')}>Archive Location</button></div>{tab === 'folders' ? <div className="space-y-5 p-6"><div className="rounded-md bg-[#edf4fb] p-4 text-xs leading-5 text-[#49627e]">Documents are connected to student folders by Student ID. If a matching folder does not exist, the archive creates one using this naming format.</div><Field label="Student folder naming format" value={format} onChange={setFormat} placeholder="{Student ID} - {Student Name}" required /><Field label="Required details when uploading a document" value={uploadRequirements} onChange={setUploadRequirements} placeholder="Student ID, student name, document type" required /><Field label="Required details when creating a folder" value={folderRequirements} onChange={setFolderRequirements} placeholder="Student ID, student name, program" required /><div className="flex justify-end"><Button onClick={save}><Check size={14} />Save folder settings</Button></div></div> : <div className="space-y-5 p-6"><div className="rounded-md border border-[#e7ebef] p-4"><div className="label-caps">Current archive destination</div><div className="mono mt-2 break-all text-xs text-[#34445a]">{destination}</div><div className="mt-2 text-[11px] text-[#8490a0]">This destination is used when Admins archive documents.</div></div><Field label="Archive location" value={destination} onChange={setDestination} placeholder="/Users/registrar/Documents/adzu-archive" required /><div className="flex items-center justify-between rounded-md border border-[#e7ebef] p-4"><div><div className="text-xs font-bold text-[#34445a]">Archive availability</div><div className="mt-1 text-[11px] text-[#8490a0]">{archiveActive ? 'New archive actions are allowed.' : 'New archive actions are paused.'}</div></div><button onClick={() => setArchiveActive(!archiveActive)} className={cx('relative h-7 w-12 rounded-full', archiveActive ? 'bg-[#2b9b72]' : 'bg-[#b33d45]')}><span className={cx('absolute top-1 h-5 w-5 rounded-full bg-white shadow-sm transition-transform', archiveActive ? 'translate-x-6' : 'translate-x-1')} /></button></div><div className="flex justify-end"><Button onClick={save}><Check size={14} />Save archive location</Button></div></div>}{notice && <div className="border-t border-[#e7ebef] bg-[#e7f6ef] px-6 py-3 text-xs font-semibold text-[#277854]">{notice}</div>}</div></div>;
}

function AdminSettingsTabs({ archiveActive, setArchiveActive, archiveDestination, onArchiveActiveChange, onDestinationChange }: { archiveActive: boolean; setArchiveActive: (value: boolean) => void; archiveDestination: string; onArchiveActiveChange: (value: boolean) => Promise<void>; onDestinationChange: (value: string) => void }) {
  const [tab, setTab] = useState<'folders' | 'location'>('folders'); const [format, setFormat] = useState('{Student ID} - {Student Name}'); const [uploadRequirements, setUploadRequirements] = useState('Student ID, student name, document type'); const [folderRequirements, setFolderRequirements] = useState('Student ID, student name, program'); const [destination, setDestination] = useState(archiveDestination); const [notice, setNotice] = useState('');
  useEffect(() => { fetch('/api/archive/settings', { credentials: 'include' }).then(response => response.ok ? response.json() : null).then(settings => { if (!settings) return; setArchiveActive(settings.archiveActive); setDestination(settings.destination); setFormat(settings.folderNamingFormat ?? format); setUploadRequirements(settings.requiredUploadDetails ?? uploadRequirements); setFolderRequirements(settings.requiredFolderDetails ?? folderRequirements); }).catch(() => undefined); }, []);
  const chooseFolder = async () => { const picker = (window as Window & { showDirectoryPicker?: () => Promise<{ name: string }> }).showDirectoryPicker; if (!picker) { setNotice('This browser does not support the native folder picker.'); return; } try { const folder = await picker(); setDestination(folder.name); setNotice('Folder selected. Save archive location to apply it.'); } catch { /* User cancelled the native picker. */ } };
  const save = async () => { const response = await fetch('/api/archive/settings', { method: 'PATCH', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ archiveActive, autoIndex: true, retention: 'Permanent', destination, folderNamingFormat: format, requiredUploadDetails: uploadRequirements, requiredFolderDetails: folderRequirements }) }); if (response.ok) { const saved = await response.json(); setDestination(saved.destination); onDestinationChange(saved.destination); setNotice('Settings saved successfully.'); } else setNotice('Settings could not be saved.'); window.setTimeout(() => setNotice(''), 3000); };
  return <div className="mx-auto max-w-[1050px] p-5 sm:p-7"><PageHeader eyebrow="Administration" title="System Settings" description="Configure folder rules, document requirements, and the archive location." /><div className="surface-card overflow-hidden rounded-lg"><div className="flex border-b border-[#e8ebef]"><button onClick={() => setTab('folders')} className={cx('px-5 py-4 text-xs font-bold', tab === 'folders' ? 'border-b-2 border-[#24558d] text-[#24558d]' : 'text-[#8a96a5]')}>Student Folder &amp; Document Settings</button><button onClick={() => setTab('location')} className={cx('px-5 py-4 text-xs font-bold', tab === 'location' ? 'border-b-2 border-[#24558d] text-[#24558d]' : 'text-[#8a96a5]')}>Archive Location</button></div>{tab === 'folders' ? <div className="space-y-5 p-6"><div className="rounded-md bg-[#edf4fb] p-4 text-xs leading-5 text-[#49627e]">Documents are connected to student folders by Student ID. If a matching folder does not exist, the archive creates one using this naming format.</div><Field label="Student folder naming format" value={format} onChange={setFormat} placeholder="{Student ID} - {Student Name}" required /><Field label="Required details when uploading a document" value={uploadRequirements} onChange={setUploadRequirements} placeholder="Student ID, student name, document type" required /><Field label="Required details when creating a folder" value={folderRequirements} onChange={setFolderRequirements} placeholder="Student ID, student name, program" required /><div className="flex justify-end"><Button onClick={save}><Check size={14} />Save folder settings</Button></div></div> : <div className="space-y-5 p-6"><div className="rounded-md border border-[#e7ebef] p-4"><div className="label-caps">Current archive destination</div><div className="mono mt-2 break-all text-xs text-[#34445a]">{destination}</div><div className="mt-2 text-[11px] text-[#8490a0]">The Dashboard Archive switch and archive actions use this configuration.</div></div><div className="flex flex-col gap-3 sm:flex-row sm:items-end"><div className="flex-1"><Field label="Archive location" value={destination} onChange={setDestination} placeholder="Select an archive folder" required /></div><Button variant="secondary" onClick={chooseFolder}><FolderOpen size={14} />Choose folder</Button></div><div className="flex items-center justify-between rounded-md border border-[#e7ebef] p-4"><div><div className="text-xs font-bold text-[#34445a]">Archive availability</div><div className="mt-1 text-[11px] text-[#8490a0]">{archiveActive ? 'New archive actions are allowed.' : 'New archive actions are paused.'}</div></div><button data-testid="button-toggle-archive-settings" onClick={() => void onArchiveActiveChange(!archiveActive)} className={cx('relative h-7 w-12 rounded-full', archiveActive ? 'bg-[#2b9b72]' : 'bg-[#b33d45]')}><span className={cx('absolute top-1 h-5 w-5 rounded-full bg-white shadow-sm transition-transform', archiveActive ? 'translate-x-6' : 'translate-x-1')} /></button></div><div className="flex justify-end"><Button onClick={save}><Check size={14} />Save archive location</Button></div></div>}{notice && <div className="border-t border-[#e7ebef] bg-[#e7f6ef] px-6 py-3 text-xs font-semibold text-[#277854]">{notice}</div>}</div></div>;
}

function ReadOnlySettings({ archiveActive }: { archiveActive: boolean }) {
  return <div className="mx-auto max-w-[1050px] p-5 sm:p-7"><PageHeader eyebrow="System information" title="System Settings" description="Regular User access is read-only." /><div className="surface-card rounded-lg p-6"><div className="flex items-center gap-3"><div className={cx('rounded-full p-2.5', archiveActive ? 'bg-[#e5f5ee] text-[#2b9b72]' : 'bg-[#fff0f0] text-[#b33d45]')}>{archiveActive ? <CircleCheck size={18} /> : <CircleAlert size={18} />}</div><div><div className="text-sm font-bold text-[#34445a]">{archiveActive ? 'Archive is active' : 'Archive is inactive'}</div><div className="mt-1 text-xs text-[#8591a0]">Only Admins can edit archive status, indexing, retention, and destinations.</div></div></div><div className="mt-6 grid gap-3 sm:grid-cols-3"><div className="rounded-md border border-[#e7ebef] p-4"><div className="label-caps">Automatic indexing</div><div className="mt-2 text-sm font-bold text-[#34445a]">Enabled</div></div><div className="rounded-md border border-[#e7ebef] p-4"><div className="label-caps">Retention</div><div className="mt-2 text-sm font-bold text-[#34445a]">Permanent</div></div><div className="rounded-md border border-[#e7ebef] p-4"><div className="label-caps">Destination</div><div className="mono mt-2 break-all text-[10px] text-[#65758a]">/Users/registrar/Documents/adzu-archive</div></div></div></div></div>;
}

function AccessDenied() {
  return <div className="mx-auto max-w-[720px] p-5 sm:p-7"><div className="surface-card rounded-lg p-8 text-center"><ShieldAlert size={30} className="mx-auto text-[#b33d45]" /><h1 className="mt-4 text-lg font-bold text-[#263950]">Admin access required</h1><p className="mt-2 text-sm text-[#718096]">This archive area is restricted to Admin accounts. Your session remains read-only.</p></div></div>;
}

function AppContent() {
  const [location, setLocation] = useLocation();
  const [loggedIn, setLoggedIn] = useState(() => localStorage.getItem('adzu-auth') === 'true');
  const [role, setRole] = useState<UserRole>(() => localStorage.getItem('adzu-role') === 'Admin' ? 'Admin' : 'Regular User');
  const [identity, setIdentity] = useState<SessionIdentity>(() => ({ userId: localStorage.getItem('adzu-user-id') ?? '', email: localStorage.getItem('adzu-email') ?? '', displayName: localStorage.getItem('adzu-display-name') ?? 'Archive User', role: localStorage.getItem('adzu-role') === 'Admin' ? 'Admin' : 'Regular User' }));
  const [documents, setDocuments] = useStored<DocumentType[]>('adzu-document-types', seedDocumentTypes);
  const [folders, setFolders] = useStored<StudentFolder[]>('adzu-student-folders', seedFolders);
  const [uploads, setUploads] = useStored<UploadRecord[]>('adzu-upload-records', seedUploads);
  const [activity, setActivity] = useStored<ActivityItem[]>('adzu-activity', seedActivity);
  const [archiveActive, setArchiveActive] = useStored<boolean>('adzu-archive-active', true);
  const [archiveDestination, setArchiveDestination] = useStored<string>('adzu-archive-destination', '/Users/registrar/Documents/adzu-archive');
  const addActivity = async (action: string, subject: string, metadata?: { folder?: string; document?: string }) => {
    const localItem: ActivityItem = { id: `act-${Date.now()}`, action, subject, actor: identity.displayName, userId: identity.userId, role, folder: metadata?.folder ?? null, document: metadata?.document ?? null, status: 'Success', timestamp: new Date().toISOString() };
    setActivity(previous => [localItem, ...previous]);
    await fetch('/api/activity', { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ action, subject, folder: metadata?.folder ?? null, document: metadata?.document ?? null, status: 'Success' }) }).catch(() => undefined);
  };
  const updateArchiveActive = async (value: boolean) => {
    const response = await fetch('/api/archive/settings', { method: 'PATCH', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ archiveActive: value }) });
    if (!response.ok) return;
    const settings = await response.json() as { archiveActive: boolean; destination: string };
    setArchiveActive(settings.archiveActive);
    setArchiveDestination(settings.destination);
  };
  useEffect(() => {
    if (!loggedIn) return;
    fetch('/api/session/me', { credentials: 'include' }).then(async response => {
      if (!response.ok) { localStorage.removeItem('adzu-auth'); setLoggedIn(false); return; }
      const session = await response.json() as SessionIdentity;
      setRole(session.role);
      setIdentity(session);
      localStorage.setItem('adzu-role', session.role);
      localStorage.setItem('adzu-user-id', session.userId);
      localStorage.setItem('adzu-email', session.email);
      localStorage.setItem('adzu-display-name', session.displayName);
      const settingsResponse = await fetch('/api/archive/settings', { credentials: 'include' });
      if (settingsResponse.ok) {
        const settings = await settingsResponse.json() as { archiveActive: boolean; destination: string };
        setArchiveActive(settings.archiveActive);
        setArchiveDestination(settings.destination);
      }
      if (session.role === 'Admin') {
        const auditResponse = await fetch('/api/activity', { credentials: 'include' });
        if (auditResponse.ok) {
          const serverActivity = await auditResponse.json() as Array<ActivityItem & { id: number }>;
          setActivity(serverActivity.map(item => ({ ...item, id: String(item.id) })));
        }
      }
    }).catch(() => undefined);
  }, [loggedIn, setActivity]);
  useEffect(() => { if (loggedIn && location === '/') setLocation('/dashboard'); }, [loggedIn, location, setLocation]);
  if (!loggedIn) return <Login onLogin={async nextIdentity => { setRole(nextIdentity.role); setIdentity(nextIdentity); localStorage.setItem('adzu-user-id', nextIdentity.userId); localStorage.setItem('adzu-email', nextIdentity.email); localStorage.setItem('adzu-display-name', nextIdentity.displayName); setLoggedIn(true); setLocation('/dashboard'); await addActivity('Logged in', 'Archive session'); }} />;
  const isAdmin = role === 'Admin';
  const ownActivity = activity.filter(item => item.userId === identity.userId);
  const page = location === '/search' ? <SearchResults folders={folders} addActivity={addActivity} setLocation={setLocation} /> : location === '/folders' ? (isAdmin ? <Folders folders={folders} setFolders={setFolders} addActivity={addActivity} setLocation={setLocation} role={role} /> : <ReadOnlyFolders folders={folders} addActivity={addActivity} title="Student folders" />) : location === '/documents' ? (isAdmin ? <Documents documents={documents} setDocuments={setDocuments} addActivity={addActivity} /> : <AccessDenied />) : location === '/upload' ? (isAdmin ? <ScanWizard uploads={uploads} setUploads={setUploads} folders={folders} setFolders={setFolders} addActivity={addActivity} documents={documents} archiveActive={archiveActive} /> : <AccessDenied />) : location === '/activity' ? (isAdmin ? <ActivityPage activity={activity} /> : <AccessDenied />) : location === '/settings' ? (isAdmin ? <AdminSettingsTabs archiveActive={archiveActive} setArchiveActive={setArchiveActive} archiveDestination={archiveDestination} onArchiveActiveChange={updateArchiveActive} onDestinationChange={setArchiveDestination} /> : <ReadOnlySettings archiveActive={archiveActive} />) : (isAdmin ? <Dashboard folders={folders} documents={documents} uploads={uploads} activity={activity} archiveActive={archiveActive} archiveDestination={archiveDestination} onArchiveToggle={updateArchiveActive} setLocation={setLocation} /> : <RegularDashboard folders={folders} uploads={uploads} activity={ownActivity} archiveActive={archiveActive} />);
  return <Shell archiveActive={archiveActive} identity={identity} onLogout={async () => { await addActivity('Logged out', 'Archive session'); await fetch('/api/session/logout', { method: 'POST', credentials: 'include' }); localStorage.removeItem('adzu-auth'); setLoggedIn(false); setLocation('/'); }}>{page}</Shell>;
}

function App() {
  return <QueryClientProvider client={new QueryClient()}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><ErrorBoundary resetKey={location.pathname}><AppContent /></ErrorBoundary></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}

export default App;